Here is a script to generate thumbnails. It assumes that you are using a Node.js server with fs and sharp packages installed. It also assumes that you have a function `getVideoList()` that returns a list of video paths.

```javascript
const fs = require('fs');
const sharp = require('sharp');

async function generateThumbnails() {
    const videoList = await getVideoList();
    const thumbnailDirectory = 'thumbnail_dir';

    if (!fs.existsSync(thumbnailDirectory)) {
        fs.mkdirSync(thumbnailDirectory);
    }

    for (let i = 0; i < videoList.length; i++) {
        const videoPath = videoList[i];
        const thumbnailPath = `${thumbnailDirectory}/${i}.jpg`;

        if (fs.existsSync(thumbnailPath)) {
            console.log(`Thumbnail for ${videoPath} already exists.`);
            continue;
        }

        sharp(videoPath)
           .resize(320, 180)
           .toFormat('jpeg', { quality: 80 })
           .toFile(thumbnailPath)
           .then(() => console.log(`Thumbnail created for ${videoPath}`))
           .catch((error) => console.error(`Error creating thumbnail for ${videoPath}`, error));
    }
}

generateThumbnails();
